css:
.wf-icon-tab { display: inline-flex; align-items: center; gap: 0.4em; font-family: var(--ps-font-display, var(--pds-font-display)); color: var(--pds-text-primary); text-decoration: none; }
.wf-icon-tab svg { width: 1.1em; height: 1.1em; fill: currentColor; }
.wf-icon-tab:hover { color: var(--pds-link); }
.wf-icon-tab:focus-visible { outline: 2px solid var(--pds-interactive-focus); outline-offset: 2px; }
